import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define THREADS_X 16
#define THREADS_Y 16
#define STAGES 3
__global__ __launch_bounds__(256, 2) void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int N) {
    __shared__ float As[STAGES][BK][BM];
    __shared__ float Bs[STAGES][BK][BN];
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++)
        #pragma unroll
        for (int j = 0; j < TN; j++)
            acc[i][j] = 0.0f;
    int numTiles = N / BK;
    int loadA_row = tid / (BK / 4);
    int loadA_col = (tid % (BK / 4)) * 4;
    int loadB_row = tid / (BN / 4);
    int loadB_col = (tid % (BN / 4)) * 4;
    // Prefetch stage 0
    {
        int global_row = by * BM + loadA_row;
        int global_col = 0 * BK + loadA_col;
        float4 val = *reinterpret_cast<const float4*>(&A[global_row * N + global_col]);
        As[0][loadA_col + 0][loadA_row] = val.x;
        As[0][loadA_col + 1][loadA_row] = val.y;
        As[0][loadA_col + 2][loadA_row] = val.z;
        As[0][loadA_col + 3][loadA_row] = val.w;
    }
    {
        int global_row = 0 * BK + loadB_row;
        int global_col = bx * BN + loadB_col;
        float4 val = *reinterpret_cast<const float4*>(&B[global_row * N + global_col]);
        *reinterpret_cast<float4*>(&Bs[0][loadB_row][loadB_col]) = val;
    }
    // Prefetch stage 1
    if (numTiles > 1) {
        int global_row = by * BM + loadA_row;
        int global_col = 1 * BK + loadA_col;
        float4 val = *reinterpret_cast<const float4*>(&A[global_row * N + global_col]);
        As[1][loadA_col + 0][loadA_row] = val.x;
        As[1][loadA_col + 1][loadA_row] = val.y;
        As[1][loadA_col + 2][loadA_row] = val.z;
        As[1][loadA_col + 3][loadA_row] = val.w;
        int global_row_b = 1 * BK + loadB_row;
        int global_col_b = bx * BN + loadB_col;
        float4 valb = *reinterpret_cast<const float4*>(&B[global_row_b * N + global_col_b]);
        *reinterpret_cast<float4*>(&Bs[1][loadB_row][loadB_col]) = valb;
    }
    __syncthreads();
    for (int t = 0; t < numTiles; t++) {
        int computeBuf = t % STAGES;
        int loadBuf = (t + 2) % STAGES;
        if (t + 2 < numTiles) {
            int global_row = by * BM + loadA_row;
            int global_col = (t + 2) * BK + loadA_col;
            float4 val = *reinterpret_cast<const float4*>(&A[global_row * N + global_col]);
            As[loadBuf][loadA_col + 0][loadA_row] = val.x;
            As[loadBuf][loadA_col + 1][loadA_row] = val.y;
            As[loadBuf][loadA_col + 2][loadA_row] = val.z;
            As[loadBuf][loadA_col + 3][loadA_row] = val.w;
            int global_row_b = (t + 2) * BK + loadB_row;
            int global_col_b = bx * BN + loadB_col;
            float4 valb = *reinterpret_cast<const float4*>(&B[global_row_b * N + global_col_b]);
            *reinterpret_cast<float4*>(&Bs[loadBuf][loadB_row][loadB_col]) = valb;
        }
        #pragma unroll
        for (int k = 0; k < BK; k++) {
            float a_frag[TM];
            float4 a_frag4_lo = *reinterpret_cast<float4*>(&As[computeBuf][k][ty * TM]);
            float4 a_frag4_hi = *reinterpret_cast<float4*>(&As[computeBuf][k][ty * TM + 4]);
            a_frag[0] = a_frag4_lo.x; a_frag[1] = a_frag4_lo.y; a_frag[2] = a_frag4_lo.z; a_frag[3] = a_frag4_lo.w;
            a_frag[4] = a_frag4_hi.x; a_frag[5] = a_frag4_hi.y; a_frag[6] = a_frag4_hi.z; a_frag[7] = a_frag4_hi.w;
            float b_frag[TN];
            float4 b_frag4_lo = *reinterpret_cast<float4*>(&Bs[computeBuf][k][tx * TN]);
            float4 b_frag4_hi = *reinterpret_cast<float4*>(&Bs[computeBuf][k][tx * TN + 4]);
            b_frag[0] = b_frag4_lo.x; b_frag[1] = b_frag4_lo.y; b_frag[2] = b_frag4_lo.z; b_frag[3] = b_frag4_lo.w;
            b_frag[4] = b_frag4_hi.x; b_frag[5] = b_frag4_hi.y; b_frag[6] = b_frag4_hi.z; b_frag[7] = b_frag4_hi.w;
            #pragma unroll
            for (int i = 0; i < TM; i++)
                #pragma unroll
                for (int j = 0; j < TN; j++)
                    acc[i][j] += a_frag[i] * b_frag[j];
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        int row = by * BM + ty * TM + i;
        int col0 = bx * BN + tx * TN;
        float4 v0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
        float4 v1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
        *reinterpret_cast<float4*>(&C[row * N + col0]) = v0;
        *reinterpret_cast<float4*>(&C[row * N + col0 + 4]) = v1;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int N = A.size(0);

    auto C = torch::empty({N, N}, A.options());

    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid(N / BN, N / BM);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model performing square matrix multiplication (C = A * B)
    using a custom tiled CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().contiguous().float()
        B = B.cuda().contiguous().float()
        return self.matmul_op.matmul_cuda(A, B)


N = 2048 * 2


def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]


def get_init_inputs():
    return []

